import math

print("--- Fundamental Rocket Physics Calculator ---")

try:
    # Get inputs from the user
    # Initial mass: Total starting mass including fuel, structure, and payload
    initial_mass = float(input("Enter initial total rocket mass (kg): "))
    
    # Final mass: Mass after propellant is consumed (dry mass + payload)
    final_mass = float(input("Enter final mass after propellant consumption (kg): "))
    
    # Thrust: Force generated by the rocket engine
    thrust = float(input("Enter engine thrust (newtons): "))
    
    # Specific impulse (Isp): Efficiency of the rocket engine
    isp = float(input("Enter specific impulse (seconds): "))
    
    # Validate inputs
    if initial_mass <= 0 or final_mass <= 0 or thrust <= 0 or isp <= 0:
        print("\nError: All values must be strictly positive.")
    elif final_mass > initial_mass:
        print("\nError: Final mass cannot exceed initial mass.")
    else:
        # Perform calculations if inputs are valid
        
        # Standard gravity on Earth (m/s^2)
        g0 = 9.80665
        
        # A. Calculate Thrust-to-weight ratio (TWR)
        # TWR indicates if the rocket can lift off. It compares thrust to the rocket's weight.
        # A ratio > 1 indicates positive initial vertical acceleration for a stationary rocket
        # (under simplified assumptions like vertical thrust and no air drag).
        weight = initial_mass * g0
        twr = thrust / weight
        
        # B. Calculate Ideal delta-v
        # Delta-v is the total velocity change the rocket can achieve (Tsiolkovsky rocket equation).
        # It assumes idealized propulsion, ignoring gravity, atmospheric drag, and steering losses.
        mass_ratio = initial_mass / final_mass
        delta_v = isp * g0 * math.log(mass_ratio)
        
        # C. Calculate Propellant mass
        # The total mass of the fuel and oxidizer consumed.
        propellant_mass = initial_mass - final_mass
        
        # Display the results
        print("\n--- Results ---")
        print(f"Propellant mass:        {propellant_mass:.2f} kg")
        print(f"Thrust-to-weight ratio: {twr:.2f} (dimensionless)")
        print(f"Ideal delta-v:          {delta_v:.2f} m/s ({delta_v / 1000:.2f} km/s)")

except ValueError:
    print("\nError: Please enter valid numerical values.")
